"""Hash receipt for round 4: source receipts, report files read, tools, and outputs."""
import hashlib, json, subprocess, sys
from pathlib import Path
def sha(p): return hashlib.sha256(Path(p).read_bytes()).hexdigest()
root = Path('.')
res = json.load(open('report/yield-normal-v3/results.json')); ref = json.load(open('report/yield-normal-v3/refinement.json'))
receipts = {r['id']: {'path': r['path'], 'recorded_sha256': r['sha256'], 'sha256_now': sha(r['path'])} for r in res['rows']}
receipts.update({'refinement:' + r['id']: {'path': r['path'], 'recorded_sha256': r['sha256'], 'sha256_now': sha(r['path'])} for r in ref['runs']})
report_files = sorted(str(p) for p in Path('report/yield-normal-v3').glob('*') if p.is_file())
other = ['report/yield-observer-identifiability-v1/discussion/main-adjudication.md', 'report/yield-observer-identifiability-v1/discussion/fable-round3.md',
         'report/yield-normal-v2/discussion/main-adjudication.md', 'report/yield-normal-v2/discussion/discussion.md',
         'report/yield-gain-memory-v1/discussion/main-adjudication.md', 'report/yield-transfer-v1/results.md', 'report/yield-transfer-v1/README.md',
         'report/yield-gain-memory-v1/results.md', 'report/yield-normal-v2/results.md', 'report/yield-observer-identifiability-v1/prior-results.md',
         'config/yield_normal_observer_v3.json', 'config/yield_normal_frozen_prior_v1.json', 'config/contact_yield_candidates/dsfc.json']
tools = sorted(str(p) for p in Path('tools').glob('contact_yield_*.py')) + sorted(str(p) for p in Path('tools').glob('*yield_normal_v3*.py'))
outputs = sorted(str(p) for p in Path('report/yield-normal-v3/discussion').rglob('*') if p.is_file() and p.name != 'round4-manifest.json')
head = subprocess.run(['git', 'rev-parse', 'HEAD'], capture_output=True, text=True).stdout.strip()
out = {'git_head': head, 'all_receipts_match': all(v['recorded_sha256'] == v['sha256_now'] for v in receipts.values()),
       'raw_receipts': receipts, 'report_files': {p: sha(p) for p in report_files}, 'other_inputs': {p: sha(p) for p in other},
       'tools': {p: sha(p) for p in tools}, 'outputs': {p: sha(p) for p in outputs},
       'cache': '/tmp/ynv3/*.npz regenerated by scripts/extract_ticks_v3.py; not retained',
       'claim': 'read-only postprocessing of retained development receipts; no closed-loop run, no code/config/test edit'}
json.dump(out, open('report/yield-normal-v3/discussion/data/round4-manifest.json', 'w'), indent=1)
print('all_receipts_match', out['all_receipts_match'], 'head', head, 'outputs', len(outputs))
